+)
+
+type testStore struct {
+	flags         []*flipt.Flag
+	rules         []*flipt.Rule
+	segments      []*flipt.Segment
+	attachments   map[string]string
+	createdFlags  int
+	createdRules  int
+	createdDists  int
+	createdSegs   int
+	createdConstr int
+}
+
+func (s *testStore) ListFlags(_ context.Context, _ ...storage.QueryOption) ([]*flipt.Flag, error) {
+	return s.flags, nil
+}
+func (s *testStore) ListRules(_ context.Context, _ string, _ ...storage.QueryOption) ([]*flipt.Rule, error) {
+	return s.rules, nil
+}
+func (s *testStore) ListSegments(_ context.Context, _ ...storage.QueryOption) ([]*flipt.Segment, error) {
+	return s.segments, nil
+}
+func (s *testStore) CreateFlag(_ context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
+	s.createdFlags++
+	return &flipt.Flag{Key: r.Key}, nil
+}
+func (s *testStore) CreateVariant(_ context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) {
+	if s.attachments == nil {
+		s.attachments = make(map[string]string)
+	}
+	s.attachments[r.Key] = r.Attachment
+	return &flipt.Variant{Id: r.Key + "-id", Key: r.Key}, nil
+}
+func (s *testStore) CreateSegment(_ context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment, error) {
+	s.createdSegs++
+	return &flipt.Segment{Key: r.Key}, nil
+}
+func (s *testStore) CreateConstraint(_ context.Context, _ *flipt.CreateConstraintRequest) (*flipt.Constraint, error) {
+	s.createdConstr++
+	return &flipt.Constraint{}, nil
+}
+func (s *testStore) CreateRule(_ context.Context, _ *flipt.CreateRuleRequest) (*flipt.Rule, error) {
+	s.createdRules++
+	return &flipt.Rule{Id: "rule-id"}, nil
+}
+func (s *testStore) CreateDistribution(_ context.Context, r *flipt.CreateDistributionRequest) (*flipt.Distribution, error) {
+	if r.VariantId == "" || r.RuleId == "" {
+		panic("missing distribution relationship")
+	}
+	s.createdDists++
+	return &flipt.Distribution{}, nil
+}
+
+func TestExportImportAttachmentsAndHierarchy(t *testing.T) {
+	ctx := context.Background()
+	attachment := `{"nested":{"list":[1,"two",true,null,{"value":2.5}]},"empty":[],"nil":null}`
+	source := &testStore{
+		flags: []*flipt.Flag{{Key: "flag", Enabled: true, Variants: []*flipt.Variant{
+			{Id: "one-id", Key: "one", Attachment: attachment},
+			{Id: "two-id", Key: "two"},
+		}}},
+		rules:    []*flipt.Rule{{SegmentKey: "segment", Rank: 1, Distributions: []*flipt.Distribution{{VariantId: "one-id", Rollout: 50}}}},
+		segments: []*flipt.Segment{{Key: "segment", Constraints: []*flipt.Constraint{{Property: "region", Operator: "eq", Value: "US"}}}},
+	}
+	var output bytes.Buffer
+	if err := NewExporter(source).Export(ctx, &output); err != nil {
+		t.Fatal(err)
+	}
+	if strings.Contains(output.String(), `attachment: '{`) || !strings.Contains(output.String(), "nested:") {
+		t.Fatalf("attachment was not rendered as YAML: %s", output.String())
+	}
+	var doc Document
+	if err := yaml.Unmarshal(output.Bytes(), &doc); err != nil {
+		t.Fatal(err)
+	}
+	if len(doc.Flags) != 1 || len(doc.Flags[0].Rules) != 1 || len(doc.Segments) != 1 {
+		t.Fatalf("incomplete document: %+v", doc)
+	}
+
+	target := &testStore{}
+	if err := NewImporter(target).Import(ctx, &output); err != nil {
+		t.Fatal(err)
+	}
+	var got, want interface{}
+	if err := json.Unmarshal([]byte(target.attachments["one"]), &got); err != nil {
+		t.Fatal(err)
+	}
+	if err := json.Unmarshal([]byte(attachment), &want); err != nil {
+		t.Fatal(err)
+	}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("attachment changed: got %#v, want %#v", got, want)
+	}
+	if target.attachments["two"] != "" || target.createdFlags != 1 || target.createdSegs != 1 || target.createdConstr != 1 || target.createdRules != 1 || target.createdDists != 1 {
+		t.Fatalf("incomplete import: %+v", target)
+	}
+}
+
+func TestImportNestedYAMLKeys(t *testing.T) {
+	store := &testStore{}
+	input := "flags:\n- key: flag\n  enabled: true\n  variants:\n  - key: variant\n    attachment:\n      1: [{false: null}, [true, 3]]\n"
+	if err := NewImporter(store).Import(context.Background(), strings.NewReader(input)); err != nil {
+		t.Fatal(err)
+	}
+	var decoded interface{}
+	if err := json.Unmarshal([]byte(store.attachments["variant"]), &decoded); err != nil {
+		t.Fatal(err)
+	}
+	want := map[string]interface{}{"1": []interface{}{map[string]interface{}{"false": nil}, []interface{}{true, float64(3)}}}
+	if !reflect.DeepEqual(decoded, want) {
+		t.Fatalf("got %#v, want %#v", decoded, want)
+	}
+}
